import numpy as np
import matplotlib.pyplot as plt

# GNU Radio parameters
samp_rate = 32000.0

# Input files generated by GNU Radio
files = {
    "Narrow  π/3000": "ch21_exp5_pll_phase_error_narrow.dat",
    "Baseline π/1000": "ch21_exp5_pll_phase_error_baseline.dat",
    "Wide    π/300": "ch21_exp5_pll_phase_error_wide.dat",
}

output_file = "ch21-exp5-pll-loop-bandwidth-comparison.png"

plt.figure(figsize=(9, 5.2))

for label, filename in files.items():
    # Read float32 phase-error samples
    phase_error_rad = np.fromfile(filename, dtype=np.float32)

    # Convert sample index to time in milliseconds
    time_ms = np.arange(len(phase_error_rad)) / samp_rate * 1000.0

    # Convert phase error from radians to degrees
    phase_error_deg = np.degrees(phase_error_rad)

    # Plot the measured response
    plt.plot(time_ms, phase_error_deg, label=label)

plt.xlabel("Time (ms)")
plt.ylabel("Phase Error (degrees)")
plt.title("Effect of PLL Loop Bandwidth on Acquisition")
plt.ylim(-185, 185)
plt.grid(True, alpha=0.3)
plt.legend()
plt.tight_layout()

plt.savefig(output_file, dpi=200)
plt.show()
